#### story/story_player.gd
```
class_name StoryPlayer
extends Node

signal story_finished

@export var story_file_path: String = "res://story/intro.json"
@export var dialogue_box: PanelContainer
@export var character_stage: CharacterStage
@export var background_display: BackgroundDisplay

var _lines: Array = []
var _current_line_index: int = 0
var _is_transitioning: bool = false


func _ready() -> void:
	if dialogue_box:
		dialogue_box.line_finished.connect(_on_dialogue_box_line_finished)

	if load_story(story_file_path):
		start_story()


func is_transitioning() -> bool:
	return _is_transitioning or (background_display != null and background_display.is_transitioning())


func change_background(new_texture: Texture2D, transition_type: String = "crossfade", duration: float = 0.5) -> void:
	_is_transitioning = true
	if background_display:
		if transition_type == "black":
			await background_display.transition_through_black(new_texture, duration)
		else:
			await background_display.crossfade_to(new_texture, duration)
	_is_transitioning = false


func load_story(path: String) -> bool:
	if not FileAccess.file_exists(path):
		print("Errore: file della storia non trovato: ", path)
		return false

	var file := FileAccess.open(path, FileAccess.READ)
	if not file:
		print("Errore durante l'apertura del file: ", path)
		return false

	var json := JSON.new()
	var parse_result := json.parse(file.get_as_text())
	if parse_result != OK:
		print("Errore nel parsing del JSON: ", json.get_error_message())
		return false

	var data: Dictionary = json.data
	if not data.has("lines"):
		print("Errore: la chiave 'lines' non è presente nel file JSON.")
		return false

	_lines = data["lines"]
	_current_line_index = 0
	return true


func start_story() -> void:
	if _lines.is_empty():
		return
	_current_line_index = 0
	_show_current_line()


func advance() -> void:
	if is_transitioning():
		return

	_current_line_index += 1
	if _current_line_index < _lines.size():
		_show_current_line()
	else:
		if dialogue_box:
			dialogue_box.clear()
		story_finished.emit()


func get_line_count() -> int:
	return _lines.size()


func restart_story() -> void:
	if _lines.is_empty():
		return
	_current_line_index = 0
	_show_current_line()


func jump_to_line(index: int) -> bool:
	if index < 0 or index >= get_line_count():
		return false
	_current_line_index = index
	_show_current_line()
	return true


func is_at_end() -> bool:
	return _current_line_index >= get_line_count()


func get_character_stage() -> CharacterStage:
	return character_stage


func get_background_display() -> BackgroundDisplay:
	return background_display


func _show_current_line() -> void:
	if _current_line_index < 0 or _current_line_index >= _lines.size():
		return

	var line_data: Dictionary = _lines[_current_line_index]
	var speaker: String = line_data.get("speaker", "")
	var text: String = line_data.get("text", "")

	if background_display and line_data.has("background"):
		var bg_path: String = line_data["background"]
		var bg_tex: Texture2D = load(bg_path) as Texture2D
		if bg_tex:
			if dialogue_box:
				dialogue_box.clear()
			var trans_type: String = line_data.get("transition", "crossfade")
			var trans_dur: float = float(line_data.get("transition_duration", 0.5))
			await change_background(bg_tex, trans_type, trans_dur)

	if dialogue_box:
		dialogue_box.show_line(speaker, text)

	if character_stage and not speaker.is_empty():
		character_stage.focus_character(speaker.to_lower())


func _on_dialogue_box_line_finished() -> void:
	advance()
```

#### story/story_interpreter.gd
```
class_name StoryInterpreter
extends Node

signal story_finished

@export var dialogue_box: PanelContainer
@export var character_stage: CharacterStage
@export var background_display: BackgroundDisplay

var characters_data: Dictionary = {}


func _ready() -> void:
	if characters_data.is_empty():
		characters_data["elena"] = preload("res://story/elena.tres")
		characters_data["marco"] = preload("res://story/marco.tres")


func run_story(commands: Array[Dictionary]) -> void:
	for command in commands:
		await execute_command(command)
	story_finished.emit()


func execute_command(command: Dictionary) -> void:
	var command_type: String = command.get("type", "")

	match command_type:
		"line":
			await _cmd_line(command)
		"background":
			await _cmd_background(command)
		"show":
			_cmd_show(command)
		"hide":
			_cmd_hide(command)
		"expression":
			_cmd_expression(command)
		"wait":
			await _cmd_wait(command)
		"shake":
			await _cmd_shake(command)
		_:
			push_warning("Comando sconosciuto: %s" % command_type)


func _cmd_line(cmd: Dictionary) -> void:
	var speaker: String = cmd.get("speaker", "")
	var text: String = cmd.get("text", "")
	if dialogue_box:
		dialogue_box.show_line(speaker, text)
		await dialogue_box.line_finished


func _cmd_background(cmd: Dictionary) -> void:
	var texture_path: String = cmd.get("texture", "")
	if not texture_path.is_empty():
		var tex: Texture2D = load(texture_path) as Texture2D
		if tex and background_display:
			background_display.set_background(tex)


func _cmd_show(cmd: Dictionary) -> void:
	var char_id: String = cmd.get("character", "")
	var pos: String = cmd.get("position", "center")
	var data: CharacterData = characters_data.get(char_id, null)
	if data and character_stage:
		character_stage.add_character(char_id, data, pos)


func _cmd_hide(cmd: Dictionary) -> void:
	var char_id: String = cmd.get("character", "")
	if character_stage:
		character_stage.remove_character(char_id)


func _cmd_expression(cmd: Dictionary) -> void:
	var char_id: String = cmd.get("character", "")
	var expression: String = cmd.get("expression", "neutral")
	if character_stage:
		var display: CharacterDisplay = character_stage.get_character(char_id)
		if display:
			display.set_expression(expression)


func _cmd_wait(cmd: Dictionary) -> void:
	var duration: float = float(cmd.get("duration", 1.0))
	await get_tree().create_timer(duration).timeout


func _cmd_shake(cmd: Dictionary) -> void:
	var duration: float = float(cmd.get("duration", 0.3))
	var strength: float = float(cmd.get("strength", 10.0))
	if character_stage:
		var orig_pos: Vector2 = character_stage.position
		var tween: Tween = create_tween()
		tween.tween_property(character_stage, "position", orig_pos + Vector2(strength, 0.0), duration * 0.25)
		tween.tween_property(character_stage, "position", orig_pos - Vector2(strength, 0.0), duration * 0.5)
		tween.tween_property(character_stage, "position", orig_pos, duration * 0.25)
		await tween.finished
```

