extends Node

signal story_finished

@export var dialogue_box: PanelContainer
@export var character_stage: CharacterStage
@export var background_display: BackgroundDisplay
@export var choice_menu: ChoiceMenu

var characters_data: Dictionary = {}


func _ready() -> void:
	if characters_data.is_empty():
		characters_data["elena"] = preload("res://story/elena.tres")
		characters_data["marco"] = preload("res://story/marco.tres")


func run_story(commands: Array[Dictionary]) -> void:
	var labels: Dictionary = {}
	for i in range(commands.size()):
		var cmd: Dictionary = commands[i]
		if cmd.get("type", "") == "label":
			var label_id := String(cmd.get("id", ""))
			if not label_id.is_empty():
				labels[label_id] = i

	var index := 0
	while index < commands.size():
		var command: Dictionary = commands[index]
		var cmd_type: String = command.get("type", "")

		match cmd_type:
			"label":
				index += 1
			"jump":
				var target: String = command.get("target", "")
				if labels.has(target):
					index = labels[target]
				else:
					index += 1
			"choice":
				var options: Array = command.get("options", [])
				if choice_menu:
					choice_menu.show_choices(options)
					var selected_target: String = await choice_menu.choice_selected
					if labels.has(selected_target):
						index = labels[selected_target]
					else:
						index += 1
				else:
					index += 1
			_:
				await execute_command(command)
				index += 1

	story_finished.emit()


func execute_command(command: Dictionary) -> void:
	var command_type: String = command.get("type", "")

	match command_type:
		"line":
			await _cmd_line(command)
		"background":
			await _cmd_background(command)
		"show":
			_cmd_show(command)
		"hide":
			_cmd_hide(command)
		"expression":
			_cmd_expression(command)
		"wait":
			await _cmd_wait(command)
		"shake":
			await _cmd_shake(command)
		_:
			push_warning("Comando sconosciuto: %s" % command_type)


func _cmd_line(cmd: Dictionary) -> void:
	var speaker: String = cmd.get("speaker", "")
	var text: String = cmd.get("text", "")
	if dialogue_box:
		dialogue_box.show_line(speaker, text)
		await dialogue_box.line_finished


func _cmd_background(cmd: Dictionary) -> void:
	var texture_path: String = cmd.get("texture", "")
	if not texture_path.is_empty():
		var tex: Texture2D = load(texture_path) as Texture2D
		if tex and background_display:
			background_display.set_background(tex)


func _cmd_show(cmd: Dictionary) -> void:
	var char_id: String = cmd.get("character", "")
	var pos: String = cmd.get("position", "center")
	var data: CharacterData = characters_data.get(char_id, null)
	if data and character_stage:
		character_stage.add_character(char_id, data, pos)


func _cmd_hide(cmd: Dictionary) -> void:
	var char_id: String = cmd.get("character", "")
	if character_stage:
		character_stage.remove_character(char_id)


func _cmd_expression(cmd: Dictionary) -> void:
	var char_id: String = cmd.get("character", "")
	var expression: String = cmd.get("expression", "neutral")
	if character_stage:
		var display: CharacterDisplay = character_stage.get_character(char_id)
		if display:
			display.set_expression(expression)


func _cmd_wait(cmd: Dictionary) -> void:
	var duration: float = float(cmd.get("duration", 1.0))
	await get_tree().create_timer(duration).timeout


func _cmd_shake(cmd: Dictionary) -> void:
	var duration: float = float(cmd.get("duration", 0.3))
	var strength: float = float(cmd.get("strength", 10.0))
	if character_stage:
		var orig_pos: Vector2 = character_stage.position
		var tween: Tween = create_tween()
		tween.tween_property(character_stage, "position", orig_pos + Vector2(strength, 0.0), duration * 0.25)
		tween.tween_property(character_stage, "position", orig_pos - Vector2(strength, 0.0), duration * 0.5)
		tween.tween_property(character_stage, "position", orig_pos, duration * 0.25)
		await tween.finished
